package store

import (
	"errors"
	"testing"

	"github.com/jinzhu/gorm"
	"github.com/raahii/golang-grpc-realworld-example/model"
	"github.com/stretchr/testify/assert"
)

type mockDB struct {
	findFunc func(out interface{}) *gorm.DB
	rowsFunc func() (*gorm.RowsQueryResult, error)
}

func TestArticleStoreGetArticles(t *testing.T) {
	tests := []struct {
		name        string
		tagName     string
		username    string
		favoritedBy *model.User
		limit       int64
		offset      int64
		mockDB      *mockDB
		expected    []model.Article
		expectedErr error
	}{
		{
			name:        "Success",
			tagName:     "test",
			username:    "testuser",
			favoritedBy: &model.User{},
			limit:       10,
			offset:      0,
			mockDB: &mockDB{
				findFunc: func(out interface{}) *gorm.DB {
					*(out.(*[]model.Article)) = []model.Article{
						{Title: "Test Article"},
					}
					return &gorm.DB{}
				},
			},
			expected: []model.Article{
				{Title: "Test Article"},
			},
			expectedErr: nil,
		},
		{
			name: "Error",
			mockDB: &mockDB{
				findFunc: func(out interface{}) *gorm.DB {
					return &gorm.DB{Error: errors.New("database error")}
				},
			},
			expectedErr: errors.New("database error"),
		},
		{
			name:        "Empty Result",
			tagName:     "nonexistent",
			username:    "",
			favoritedBy: nil,
			limit:       20,
			offset:      5,
			mockDB: &mockDB{
				findFunc: func(out interface{}) *gorm.DB {
					*(out.(*[]model.Article)) = []model.Article{}
					return &gorm.DB{}
				},
			},
			expected:    []model.Article{},
			expectedErr: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			store := &ArticleStore{db: tt.mockDB.findFunc()}
			articles, err := store.GetArticles(tt.tagName, tt.username, tt.favoritedBy, tt.limit, tt.offset)

			if tt.expectedErr != nil {
				assert.Error(t, err)
				assert.Equal(t, tt.expectedErr.Error(), err.Error())
			} else {
				assert.NoError(t, err)
				assert.Equal(t, tt.expected, articles)
			}
		})
	}
}

